import React, { Component } from "react";
import "./HelpAnimalModal.css";

class HelpAnimalModal extends Component {
  constructor(props) {
    super(props);
    this.state = {
      microchipId: "",
    };
  }

  handleChange = (event) => {
    this.setState({ microchipId: event.target.value });
  };

  handleSubmit = () => {
    // כאן תוסיף את הקוד לפתיחת השיחה עם בעל החיה
    console.log("Open chat with owner for microchip ID:", this.state.microchipId);
    this.props.onClose();
  };

  render() {
    if (!this.props.show) {
      return null;
    }

    return (
      <div className="custom-modal">
        <div className="custom-modal-content">
          <span className="custom-modal-close" onClick={this.props.onClose}>&times;</span>
          <h2>You found a lost pet</h2>
          <p>Please write the ID of the microchip of the pet</p>
          <input
            type="text"
            value={this.state.microchipId}
            onChange={this.handleChange}
            className="custom-input"
          />
          <button onClick={this.handleSubmit} className="custom-button">Open a chat with owner</button>
        </div>
      </div>
    );
  }
}

export default HelpAnimalModal;
